        reset() {
            this._volume = 100;
            this._muted = false;
            this._playerState = "synchronized";
            this._isPlaying = false;
            this._currentStreamFormat = null;
            this._streamStartServerTime = 0;
            this._streamStartAudioTime = 0;
            this._serverState = {};
            this._groupState = {};
            this.clearAllIntervals();
        }
