        notifyStateChange() {
            if (this.onStateChangeCallback) {
                this.onStateChangeCallback({
                    isPlaying: this._isPlaying,
                    volume: this._volume,
                    muted: this._muted,
                    playerState: this._playerState,
                    serverState: this._serverState,
                    groupState: this._groupState,
                });
            }
        }
